import {packageExercises} from './packages.js';
import {addExamSheetExercises} from './exam-sheet.js';
import {courseEvidence} from './course-evidence.js';
export const topics = [
 {id:'vectors',name:'Vektorer & typer',icon:'[ ]',description:'Byg dit fundament med værdier, sekvenser og indeksering.'},
 {id:'frames',name:'Data frames',icon:'▦',description:'Lær dine data at kende. Udvælg rækker og kolonner.'},
 {id:'filter',name:'Filtrering & sortering',icon:'⇅',description:'Find de rigtige observationer med præcis logik.'},
 {id:'functions',name:'Funktioner & løkker',icon:'ƒ',description:'Gør kode genbrugelig, og tænk i vektorer.'},
 {id:'for-loops',name:'For-loops',icon:'↻',description:'Byg din første for-løkke, og lær at tælle, summere og gemme resultater.'},
 {id:'stats',name:'Statistik & NA',icon:'σ',description:'Rens data, opsummér og sammenlign grupper.'},
 {id:'simulation',name:'Simulation & modeller',icon:'⌁',description:'Fra terningekast til regression og kvartalsdata.'}
];
const sources={intro:'DALE26W35/Torsdag.R',list:'DALEW36/Pair Programming - Mandag.R',exam:'Eksamensøvning/Eksamenstræningsopgaver - Forsøg 1.R',clean:'DALEW36/Onsdag.R',loops:'Uge37/PairProgrammering10/PairProgramming1009.R',dice:'Terning/dice.R',model:'Mikroindikator/Mikroindikator.R',macro:'Mikroindikator/Mikroindikator.R',flight:'OpenSky/GetPlanes.R',consumer:'Uge37/Forbrugerforventninger.csv'};
const car='biler <- mtcars';
export const exercises=[];
function add(id,topic,title,prompt,solution,{setup='',hint='',explanation='',level=1,source='exam',starter='# Skriv din løsning her\n',check=null,kind='code',options=null,answer=null,orderMatters=true,extra=false}={}){exercises.push({id,topic,title,prompt,solution,setup,hint,explanation:explanation||hint,level,source:sources[source],starter,check,kind,options,answer,orderMatters,extra});}
const loopCheck=(object,fixtures)=>`.loop_matches(.user_expr, ${JSON.stringify(object)}, list(${fixtures.map(f=>`list(setup=${JSON.stringify(f.setup)}, reference=${JSON.stringify(f.reference)})`).join(', ')}))`;
add("basic-loop-sequence",'for-loops',"Din første for-løkke","Brug en for-løkke til at fylde resultat med tallene fra 1 til antal i stigende rækkefølge.","resultat <- integer(antal)\nfor (i in seq_len(antal)) {\n  resultat[i] <- i\n}\nresultat",{source:'loops',setup:"antal <- 4L",hint:"seq_len(antal) giver løkken én omgang for hvert tal. Gem i på plads i med resultat[i] <- i.",starter:"resultat <- integer(antal)\nfor (i in seq_len(antal)) {\n  # Gem i på plads i\n}\nresultat",check:loopCheck('resultat',[{"setup":"antal <- 4L","reference":"resultat <- integer(antal)\nfor (i in seq_len(antal)) {\n  resultat[i] <- i\n}\nresultat"},{"setup":"antal <- 7L","reference":"resultat <- integer(antal)\nfor (i in seq_len(antal)) {\n  resultat[i] <- i\n}\nresultat"}])});
add("basic-loop-sum",'for-loops',"Læg tallene sammen ét ad gangen","Brug en for-løkke over værdierne i tal. Start resultat på 0 og læg én værdi til ad gangen.","resultat <- 0\nfor (vaerdi in tal) {\n  resultat <- resultat + vaerdi\n}\nresultat",{source:'loops',setup:"tal <- c(4, 2, 7)",hint:"resultat skal oprettes før løkken. Inden i løkken opdaterer du den løbende sum.",check:loopCheck('resultat',[{"setup":"tal <- c(4, 2, 7)","reference":"resultat <- 0\nfor (vaerdi in tal) {\n  resultat <- resultat + vaerdi\n}\nresultat"},{"setup":"tal <- c(-3, 5, 0, 2)","reference":"resultat <- 0\nfor (vaerdi in tal) {\n  resultat <- resultat + vaerdi\n}\nresultat"}])});
add("basic-loop-double",'for-loops',"Gem et resultat på hver plads","Brug en for-løkke til at fordoble hvert tal. Gem de nye værdier i resultat i samme rækkefølge.","resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- 2 * tal[i]\n}\nresultat",{source:'loops',setup:"tal <- c(3, 1, 6)",hint:"seq_along(tal) giver positionerne. Brug tal[i] til at hente værdien og resultat[i] til at gemme svaret.",check:loopCheck('resultat',[{"setup":"tal <- c(3, 1, 6)","reference":"resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- 2 * tal[i]\n}\nresultat"},{"setup":"tal <- c(5, 0, -2, 9)","reference":"resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- 2 * tal[i]\n}\nresultat"}])});
add("basic-loop-count",'for-loops',"Tæl med for og if","Brug en for-løkke og if til at tælle, hvor mange værdier i tal der er større end graense. Gem antallet i resultat.","resultat <- 0\nfor (vaerdi in tal) {\n  if (vaerdi > graense) {\n    resultat <- resultat + 1\n  }\n}\nresultat",{source:'loops',setup:"tal <- c(5, 8, 2, 10)\ngraense <- 5",hint:"Læg kun 1 til tælleren inde i if-blokken. > betyder, at værdier lig med grænsen ikke tæller med.",check:loopCheck('resultat',[{"setup":"tal <- c(5, 8, 2, 10)\ngraense <- 5","reference":"resultat <- 0\nfor (vaerdi in tal) {\n  if (vaerdi > graense) {\n    resultat <- resultat + 1\n  }\n}\nresultat"},{"setup":"tal <- c(3, 1, 4, 3)\ngraense <- 3","reference":"resultat <- 0\nfor (vaerdi in tal) {\n  if (vaerdi > graense) {\n    resultat <- resultat + 1\n  }\n}\nresultat"}])});
add("basic-loop-rows",'for-loops',"Gennemgå rækker i et data frame","Brug en for-løkke til at beregne antal gange pris for hver række i varer. Gem beløbene i resultat i rækkefølge.","resultat <- numeric(nrow(varer))\nfor (i in seq_len(nrow(varer))) {\n  resultat[i] <- varer$antal[i] * varer$pris[i]\n}\nresultat",{source:'loops',setup:"varer <- data.frame(antal = c(2, 3), pris = c(10, 5))",hint:"nrow(varer) giver antallet af rækker. Brug i til at slå begge værdier op på samme række.",check:loopCheck('resultat',[{"setup":"varer <- data.frame(antal = c(2, 3), pris = c(10, 5))","reference":"resultat <- numeric(nrow(varer))\nfor (i in seq_len(nrow(varer))) {\n  resultat[i] <- varer$antal[i] * varer$pris[i]\n}\nresultat"},{"setup":"varer <- data.frame(antal = c(1, 0, 4), pris = c(20, 9, 2))","reference":"resultat <- numeric(nrow(varer))\nfor (i in seq_len(nrow(varer))) {\n  resultat[i] <- varer$antal[i] * varer$pris[i]\n}\nresultat"}])});
add('basic-loop-flight','for-loops','Gennemgå svar for flere fly','Brug en for-løkke over listen svar. Opret resultat med én plads pr. svar, og start med NA på alle pladser. Hvis status_code er 200, gemmer du sd(true_track, na.rm = TRUE) på samme plads i resultat. Behold NA for andre statuskoder.',"resultat <- rep(NA_real_, length(svar))\nfor (i in seq_along(svar)) {\n  fly <- svar[[i]]\n  if (fly$status_code == 200) {\n    resultat[i] <- sd(fly$true_track, na.rm = TRUE)\n  }\n}\nresultat",{level:2,source:'flight',setup:"svar <- list(list(status_code=200, true_track=c(10,20,NA)), list(status_code=404), list(status_code=200, true_track=c(30,34,38)))",hint:'Brug seq_along(svar) og svar[[i]]. Beregn kun standardafvigelsen inde i if-blokken.',check:loopCheck('resultat',[{"setup":"svar <- list(list(status_code=200, true_track=c(10,20,NA)), list(status_code=404), list(status_code=200, true_track=c(30,34,38)))","reference":"resultat <- rep(NA_real_, length(svar))\nfor (i in seq_along(svar)) {\n  fly <- svar[[i]]\n  if (fly$status_code == 200) {\n    resultat[i] <- sd(fly$true_track, na.rm = TRUE)\n  }\n}\nresultat"},{"setup":"svar <- list(list(status_code=503), list(status_code=200, true_track=c(2,6,NA,10)))","reference":"resultat <- rep(NA_real_, length(svar))\nfor (i in seq_along(svar)) {\n  fly <- svar[[i]]\n  if (fly$status_code == 200) {\n    resultat[i] <- sd(fly$true_track, na.rm = TRUE)\n  }\n}\nresultat"}])});
add('v-seq','vectors','En vektor med alder','Opret en vektor med navnet alder. Den skal indeholde alle hele tal fra og med 15 til og med 50 i stigende rækkefølge.','alder <- seq(15, 50)',{source:'intro',hint:'seq(fra, til) eller operatoren : laver en sekvens.',check:'isTRUE(all.equal(alder, 15:50))'});
add('v-income','vectors','Indkomst i faste trin','Opret en vektor med navnet indkomst med præcis 36 værdier. Første værdi skal være 10000, og hver ny værdi skal være 5000 større end den forrige. Lad R beregne værdierne.','indkomst <- seq(10000, by = 5000, length.out = 36)',{source:'intro',hint:'Brug seq(from = start, by = trin, length.out = antal). R beregner selv slutværdien.',check:'isTRUE(all.equal(indkomst, seq(10000, by = 5000, length.out = 36)))'});
add('v-types','vectors','Hvilken datatype?','Hvad returnerer typeof(x)?','"character"',{source:'list',kind:'choice',setup:'x <- c(2L, "5", TRUE)',options:['integer','double','character','logical'],answer:2,hint:'En vektor har én fælles datatype.',explanation:'Tekst får de øvrige værdier til at blive konverteret til character.'});
add('v-index','vectors','Hver anden værdi','Hent værdierne på plads 1, 3 og 5 i vektoren x. Skriv R-kode, der returnerer disse tre værdier; du skal ikke skrive værdierne manuelt.','x[c(1, 3, 5)]',{source:'list',setup:'x <- c(4, 9, 2, 15, 7, 12)',hint:'Indeks angiver positioner, ikke værdier.'});
add('v-logic','vectors','Læs en logisk vektor','Hvilke værdier er tilbage, når koden vælger værdier fra x, som er større end 7? Skriv selve værdierne med mellemrum imellem. Rækkefølgen i dit svar er ligegyldig.','9 15 12',{source:'list',kind:'output',setup:'x <- c(4, 9, 2, 15, 7, 12)\nx[x > 7]',hint:'Kun positioner med TRUE bliver udvalgt.',answer:'9 15 12',orderMatters:false});
add('v-matrix','vectors','Byg en matrix','Opret en matrix med navnet m med 3 rækker og 2 kolonner. Brug tallene 1 til 6. Fyld først hele den første kolonne oppefra og ned og derefter den anden kolonne.','m <- matrix(1:6, nrow = 3)',{source:'list',hint:'matrix() fylder som standard kolonnevis.',check:'isTRUE(all.equal(m, matrix(1:6, nrow=3)))'});
add('v-list','vectors','Ind i en liste','Hent værdien alder, som ligger i person inde i listen profil. Returnér selve alderen som et tal.','profil$person$alder',{source:'list',setup:'profil <- list(person = list(navn = "Kim", alder = 24), interesser = c("R", "data"))',hint:'Brug $ eller [[ ]] for at hente et element fra en liste.'});
add('v-brackets','vectors','Ét eller to sæt parenteser?','Hvad er længden af ml[1]?','1',{source:'list',kind:'choice',setup:'ml <- list(1:3, 1:6, 1:7)\nlength(ml[1])',options:['1','3','6','16'],answer:0,hint:'[ ] bevarer listen; [[ ]] henter indholdet.',explanation:'ml[1] er en liste med ét element. length(ml[[1]]) ville være 3.'});
add('d-head','frames','Mød dit datasæt','Returnér de første 6 rækker af biler.','head(biler, 6)',{setup:car,hint:'head() viser som standard de første seks rækker.'});
add('d-dim','frames','Rækker og kolonner','Returnér en vektor med præcis to tal fra datasættet biler: først antallet af rækker, derefter antallet af kolonner. Formatet skal være c(antal_rækker, antal_kolonner).','dim(biler)',{setup:car,hint:'dim() returnerer begge dimensioner.'});
add('d-column','frames','Hent en kolonne','Hent kolonnen mpg fra datasættet biler. Returnér kolonnens tal som en vektor, ikke som et data frame.','biler$mpg',{setup:car,hint:'$ henter en navngiven kolonne.'});
add('d-select','frames','To kolonner, alle biler','Returnér et data frame med mpg og hp i den rækkefølge.','biler[, c("mpg", "hp")]',{setup:car,hint:'Formatet er data[rækker, kolonner]. Et tomt felt før komma vælger alle rækker.'});
add('d-last','frames','Den sidste observation','Returnér den sidste række som et data frame.','biler[nrow(biler), ]',{setup:car,hint:'nrow(biler) giver rækkenummeret på den sidste observation.'});
add('d-kw','frames','Fra hestekræfter til kW','Opret en ny kolonne med navnet hp_kw i datasættet biler. Brug formlen: hp_kw = hp * 0.7457, hvor hp er bilens hestekræfter i kolonnen hp. Beregn værdien for hver række med R.','biler$hp_kw <- biler$hp * 0.7457',{setup:car,hint:'Brug biler$hp til at hente hestekræfterne. Gang dem med 0.7457, og gem resultatet i biler$hp_kw med <- eller =.',check:'isTRUE(all.equal(biler$hp_kw, mtcars$hp * 0.7457))'});
add('d-weight','frames','Fra pund til kilogram','Opret en ny kolonne med navnet weight_kg i datasættet biler. Kolonnen wt angiver vægt i 1000 pund. Brug formlen: weight_kg = wt * 1000 * 0.453592. Faktoren 1000 omregner til pund, og 0.453592 omregner pund til kg.','biler$weight_kg <- biler$wt * 1000 * 0.453592',{setup:car,hint:'Hent vægtene med biler$wt. Gang med både 1000 og 0.453592, og gem resultatet i biler$weight_kg. Lad R udføre gangestykkerne.',check:'isTRUE(all.equal(biler$weight_kg, mtcars$wt * 1000 * 0.453592))'});
add('d-drop','frames','Fravælg kolonner','Datasættet biler er allerede oprettet for dig og indeholder kolonnerne disp og carb. Returnér datasættet uden disse to kolonner. Behold alle rækker og den oprindelige rækkefølge af de øvrige kolonner.','biler[, !names(biler) %in% c("disp", "carb")]',{setup:car,level:2,hint:'Du kan fx bruge select(biler, -disp, -carb) eller biler |> select(-disp, -carb). Med base R kan du bruge names(), %in% og !. disp og carb er kolonnenavne i biler, ikke selvstændige objekter.'});
add('d-filter-columns','frames','Vælg rækker og kolonner','Returnér et data frame med kolonnerne mpg, cyl og hp i den rækkefølge. Medtag kun biler med mindst 6 cylindre. Behold bilernes oprindelige rækkefølge.','biler[biler$cyl >= 6, c("mpg", "cyl", "hp")]',{setup:car,source:'exam',level:1,hint:'Vælg først rækkerne med cyl >= 6, og vælg derefter kolonnerne i den ønskede rækkefølge.'});
add('d-add-flag','frames','Tilføj en logisk kolonne','Tilføj kolonnen bruger_lidt_benzin til biler. Den skal være TRUE, når mpg er mindst 25, og ellers FALSE. Behold alle eksisterende kolonner og rækker. Returnér det opdaterede data frame biler.','biler$bruger_lidt_benzin <- biler$mpg >= 25\nbiler',{setup:car,source:'macro',level:1,hint:'En sammenligning som mpg >= 25 giver én TRUE/FALSE-værdi pr. række. Gem vektoren som en ny kolonne i biler.'});
add('d-filter-transform','frames','Filtrér, omregn og sortér','Brug biler til at lave resultatet med kolonnerne mpg, cyl og km_pr_liter i netop den rækkefølge. Medtag kun biler med 4 eller 6 cylindre og mpg på mindst 20. Beregn km_pr_liter med formlen: km_pr_liter = mpg * 0.42514. Sortér resultatet fra højest til lavest km_pr_liter.','resultat <- biler[biler$cyl %in% c(4, 6) & biler$mpg >= 20, c("mpg", "cyl")]\nresultat$km_pr_liter <- resultat$mpg * 0.42514\nresultat <- resultat[, c("mpg", "cyl", "km_pr_liter")]\nresultat[order(resultat$km_pr_liter, decreasing = TRUE), ]',{setup:car,source:'exam',level:2,hint:'Gør det i trin: filtrér rækker, beregn den nye kolonne, vælg kolonnerne i rækkefølge, og sortér til sidst efter km_pr_liter.'});
add('d-clean-rows','frames','Rens rækker med manglende værdier','Returnér kolonnerne model, mpg og hp i den rækkefølge. Medtag kun målinger med mindst 6 cylindre, hvor både mpg og hp er kendt. Behold den oprindelige rækkefølge.','maaling[maaling$cyl >= 6 & !is.na(maaling$mpg) & !is.na(maaling$hp), c("model", "mpg", "hp")]',{source:'clean',level:2,setup:'maaling <- data.frame(model = c("A", "B", "C", "D", "E", "F"), mpg = c(NA, 22, 18, 25, 17, 21), hp = c(110, NA, 120, 140, 90, 130), cyl = c(4, 6, 6, 8, 8, 6))',hint:'Kombinér cyl >= 6 med to kontroller af is.na(). Brug & til at kræve, at alle tre betingelser gælder i samme række.'});
add('d-group-summary','frames','Sammenlign grupper i et data frame','Lav et nyt data frame med én række pr. cyl-værdi og kolonnerne cyl og mpg. mpg skal være gennemsnittet i hver cylindergruppe.','aggregate(mpg ~ cyl, data = biler, FUN = mean)',{setup:car,source:'macro',level:2,hint:'Brug aggregate(mpg ~ cyl, data = biler, FUN = mean) eller group_by(cyl) efterfulgt af summarise(mpg = mean(mpg)).'});
add('d-best-in-group','frames','Find den bedste bil i hver gruppe','Returnér alle kolonner for den eller de biler med højest mpg inden for hver cyl-gruppe. Hvis flere biler deler gruppens højeste mpg, skal de alle med.','bedste <- aggregate(mpg ~ cyl, data = biler, FUN = max)\nmerge(bedste, biler, by = c("cyl", "mpg"))',{setup:car,source:'macro',level:3,hint:'Find først maksimum-mpg for hver cyl-gruppe. Match derefter de maksimumværdier tilbage med de oprindelige rækker. Med dplyr kan du gruppere efter cyl og filtrere mpg == max(mpg).'});
add('d-join-summary','frames','Sammenkæd salg og opsummér','Kobl salg sammen med varer via vare. Medtag kun salg af aktive varer. Beregn omsætning som antal gange pris, og returnér et data frame med kategori og samlet omsætning i kolonnen total. Der skal være én række pr. kategori. Varer uden et match i varer skal udelades.','samlet <- merge(salg, varer, by = "vare")\nsamlet <- samlet[samlet$aktiv, ]\nsamlet$oms <- samlet$antal * samlet$pris\nresultat <- aggregate(oms ~ kategori, data = samlet, FUN = sum)\nnames(resultat)[2] <- "total"\nresultat',{source:'flight',level:3,setup:'salg <- data.frame(vare = c("kaffe", "te", "te", "brød", "mælk", "ukendt"), antal = c(12, 8, 5, 4, 10, 7))\nvarer <- data.frame(vare = c("kaffe", "te", "brød", "mælk", "juice"), kategori = c("drikke", "drikke", "mad", "drikke", "drikke"), pris = c(32, 25, 28, 14, 20), aktiv = c(TRUE, TRUE, TRUE, FALSE, TRUE))',hint:'Kobl tabellerne på vare, fjern inaktive varer, opret omsætning, og opsummér derefter pr. kategori. En dplyr-løsning kan bruge left_join(), filter(), mutate(), group_by() og summarise().'});
add('d-budget-reconcile','frames','Afstem budget mod faktiske tal','Kobl budget sammen med maalt via både omraade og kvartal. Behold alle budgetrækker, også når der ikke findes et faktisk tal. Tilføj afvigelse = faktisk - budget. Returnér kolonnerne omraade, kvartal, budget, faktisk og afvigelse i den rækkefølge.','resultat <- merge(budget, maalt, by = c("omraade", "kvartal"), all.x = TRUE)\nresultat$afvigelse <- resultat$faktisk - resultat$budget\nresultat[, c("omraade", "kvartal", "budget", "faktisk", "afvigelse")]',{source:'model',level:3,setup:'budget <- data.frame(omraade = c("Nord", "Syd", "Nord", "Vest"), kvartal = c("K1", "K1", "K2", "K2"), budget = c(100, 95, 120, 80))\nmaalt <- data.frame(omraade = c("Nord", "Syd", "Nord"), kvartal = c("K1", "K1", "K2"), faktisk = c(110, 90, 130))',hint:'Match på begge nøglekolonner. Brug en venstre sammenkobling, så budgetrækker uden faktiske tal bliver stående. NA i afvigelse er forventet, når faktisk mangler.'});
add('f-hp','filter','Find de stærke biler','Returnér alle rækker fra biler, hvor kolonnen hp er større end 150. Behold alle kolonner. Biler med præcis 150 hp skal ikke med.','biler[biler$hp > 150, ]',{setup:car,hint:'Mere end betyder >. Mindst betyder >=.'});
add('f-cyl','filter','Mindst seks cylindre','Returnér alle rækker fra biler, hvor cyl er 6 eller større. Behold alle kolonner.','biler[biler$cyl >= 6, ]',{setup:car,hint:'Brug >=, så 6 også kommer med.'});
add('f-and','filter','To krav på samme tid','Returnér rækker fra biler, hvor cyl er præcis 4, og mpg samtidig er større end 20. Begge krav skal være opfyldt i samme række. Behold alle kolonner.','biler[biler$cyl == 4 & biler$mpg > 20, ]',{setup:car,level:2,hint:'& kræver at begge betingelser er sande for hver række.'});
add('f-or','filter','Enten fire eller otte','Returnér rækker fra biler, hvor cyl er enten 4 eller 8. Behold alle kolonner.','biler[biler$cyl %in% c(4, 8), ]',{setup:car,level:2,hint:'Brug %in% eller to sammenligninger med |.'});
add('f-sort','filter','Sortér hele datasættet','Returnér biler sorteret efter mpg fra lavest til højest.','biler[order(biler$mpg), ]',{setup:car,level:2,hint:'order() giver rækkernes positioner. sort() på én kolonne flytter ikke resten af rækken.'});
add('f-top','filter','De fem mest økonomiske','Returnér de 5 biler med højest mpg, i faldende rækkefølge.','head(biler[order(biler$mpg, decreasing = TRUE), ], 5)',{setup:car,level:2,hint:'Kombinér order(..., decreasing = TRUE) og head(..., 5).'});
add('f-debug','filter','Ret fejlen: OG eller ELLER','Ret koden, så den returnerer biler med 6 cylindre OG over 100 hp.','biler[biler$cyl == 6 & biler$hp > 100, ]',{setup:car,kind:'debug',starter:'biler[biler$cyl == 6 | biler$hp > 100, ]',hint:'| inkluderer rækker, der kun opfylder ét af kravene.'});
add('f-empty','filter','Når ingen rækker matcher','Hvor mange rækker returneres?','0',{kind:'output',setup:'biler <- mtcars\nnrow(biler[biler$cyl == 5 & biler$mpg > 20, ])',answer:'0',hint:'mtcars har 4, 6 eller 8 cylindre.',explanation:'Ingen biler har 5 cylindre. Et tomt data frame er et korrekt resultat.'});
add('u-temp','functions','Celsius til Fahrenheit','Opret en funktion med navnet c_til_f og argumentet x. x er temperaturen i Celsius. Brug formlen: Fahrenheit = x * 9 / 5 + 32. Funktionen skal returnere de omregnede temperaturer og virke på både ét tal og en vektor.','c_til_f <- function(x) x * 9/5 + 32',{source:'intro',level:2,hint:'Regneoperatorer i R virker elementvist på vektorer.',check:'is.function(c_til_f) && isTRUE(all.equal(c_til_f(c(-40, 0, 10, 37, 100)), c(-40, 32, 50, 98.6, 212)))'});
add('u-inches','functions','En genbrugelig omregner','Opret en funktion med navnet tommer_til_cm og argumentet x. x er længden i tommer. Brug formlen: cm = x * 2.54. Funktionen skal returnere længden i cm og virke på både ét tal og en vektor.','tommer_til_cm <- function(x) x * 2.54',{source:'intro',hint:'En funktion kan returnere sit sidste udtryk uden return().',check:'is.function(tommer_til_cm) && isTRUE(all.equal(tommer_til_cm(c(0,1,5,10)), c(0,2.54,12.7,25.4)))'});
add('u-loop','functions','Summer med en løkke','Opret et objekt med navnet total, som indeholder summen af alle tal i vektoren priser. Brug en for-løkke til at lægge priserne sammen én ad gangen.','total <- 0\nfor (pris in priser) {\n  total <- total + pris\n}',{source:'loops',setup:'priser <- c(120, 250, 80, 190)',level:2,hint:'Start en akkumulator på 0, og læg hver pris til.',check:'isTRUE(all.equal(total, sum(priser))) && any(all.names(.user_expr) == "for")'});
add('u-loop-vector','functions','Kategorisér med en løkke','Gå gennem hver alder i vektoren alder med en for-løkke. Opret vektoren kategori med én værdi pr. alder: "voksen" for mindst 18 år og "barn" ellers. Bevar rækkefølgen.','kategori <- rep(NA_character_, length(alder))\nfor (i in seq_along(alder)) {\n  if (alder[i] >= 18) {\n    kategori[i] <- "voksen"\n  } else {\n    kategori[i] <- "barn"\n  }\n}',{source:'loops',setup:'alder <- c(12, 18, 17, 45, 21)',level:3,hint:'Opret først en tom tekstvektor i samme længde som alder. Brug derefter alder[i] og if/else inde i løkken.',check:loopCheck('kategori',[{setup:'alder <- c(12, 18, 17, 45, 21)',reference:'kategori <- rep(NA_character_, length(alder))\nfor (i in seq_along(alder)) { if (alder[i] >= 18) kategori[i] <- "voksen" else kategori[i] <- "barn" }'},{setup:'alder <- c(16, 18, 22, 17, 67, 14)',reference:'kategori <- rep(NA_character_, length(alder))\nfor (i in seq_along(alder)) { if (alder[i] >= 18) kategori[i] <- "voksen" else kategori[i] <- "barn" }'}])});
add('u-loop-rows','functions','Beregn for hver række','Gå gennem rækkerne i datasættet salg med en for-løkke. Opret en numerisk vektor omsaetning med én værdi pr. række: pris gange antal. Bevar rækkefølgen.','omsaetning <- rep(0, nrow(salg))\nfor (i in seq_along(omsaetning)) {\n  omsaetning[i] <- salg$pris[i] * salg$antal[i]\n}',{source:'loops',setup:'salg <- data.frame(vare = c("kaffe", "te", "brød", "mælk"), pris = c(32, 25, 28, 14), antal = c(3, 2, 5, 4))',level:3,hint:'Brug nrow(salg) til antal gentagelser. I hver omgang hentes pris og antal fra samme række i.',check:loopCheck('omsaetning',[{setup:'salg <- data.frame(vare = c("kaffe", "te", "brød", "mælk"), pris = c(32, 25, 28, 14), antal = c(3, 2, 5, 4))',reference:'omsaetning <- rep(0, nrow(salg))\nfor (i in seq_along(omsaetning)) omsaetning[i] <- salg$pris[i] * salg$antal[i]'},{setup:'salg <- data.frame(vare = c("bog", "lampe", "stol"), pris = c(120, 450, 800), antal = c(2, 1, 3))',reference:'omsaetning <- rep(0, nrow(salg))\nfor (i in seq_along(omsaetning)) omsaetning[i] <- salg$pris[i] * salg$antal[i]'}])});
add('u-loop-list','functions','Opsummér en liste','Listen loeb indeholder flere navngivne vektorer med tider. Brug en for-løkke til at beregne gennemsnittet for hver vektor. Gem resultatet i en navngiven numerisk vektor gennemsnit med samme navne som elementerne i loeb.','gennemsnit <- rep(0, length(loeb))\nnames(gennemsnit) <- names(loeb)\nfor (i in seq_along(loeb)) {\n  gennemsnit[i] <- mean(loeb[[i]])\n}',{source:'list',setup:'loeb <- list(DHL = c(18, 20, 22), park = c(12, 16, 20), sprint = c(11, 13, 15))',level:4,hint:'Lav en resultatvektor med samme længde som listen, kopiér dens navne, og brug [[i]] til at hente hver indre vektor.',check:loopCheck('gennemsnit',[{setup:'loeb <- list(DHL = c(18, 20, 22), park = c(12, 16, 20), sprint = c(11, 13, 15))',reference:'gennemsnit <- rep(0, length(loeb)); names(gennemsnit) <- names(loeb); for (i in seq_along(loeb)) gennemsnit[i] <- mean(loeb[[i]])'},{setup:'loeb <- list(kort = c(4, 5), lang = c(9, 10, 11, 12), bane = c(6, 8, 10))',reference:'gennemsnit <- rep(0, length(loeb)); names(gennemsnit) <- names(loeb); for (i in seq_along(loeb)) gennemsnit[i] <- mean(loeb[[i]])'}])});
add('u-loop-matrix','functions','Brug to løkker på en matrix','Beregn summen af hver række i matrix m. Brug en ydre for-løkke til rækkerne og en indre for-løkke til kolonnerne. Gem rækkesummerne i vektoren raekkesum i samme rækkefølge som rækkerne.','raekkesum <- rep(0, nrow(m))\nfor (i in seq_along(raekkesum)) {\n  for (j in seq_along(m[i, ])) {\n    raekkesum[i] <- raekkesum[i] + m[i, j]\n  }\n}',{source:'list',setup:'m <- matrix(c(5, 7, 10, 11, 13, 15), nrow = 3)',level:4,hint:'Initialisér én sum pr. række. Den ydre løkke vælger i; den indre løkke lægger m[i, j] til for hver kolonne j.',check:loopCheck('raekkesum',[{setup:'m <- matrix(c(5, 7, 10, 11, 13, 15), nrow = 3)',reference:'raekkesum <- rep(0, nrow(m)); for (i in seq_along(raekkesum)) for (j in seq_along(m[i, ])) raekkesum[i] <- raekkesum[i] + m[i, j]'},{setup:'m <- matrix(1:8, nrow = 4, ncol = 2)',reference:'raekkesum <- rep(0, nrow(m)); for (i in seq_along(raekkesum)) for (j in seq_along(m[i, ])) raekkesum[i] <- raekkesum[i] + m[i, j]'}])});
add('u-loop-time','functions','Beregn ændringer over tid','indeks indeholder månedlige værdier for forbrugertillidsindikatoren. Brug en for-løkke til at beregne ændringen fra hver måned til den foregående: denne måneds værdi minus sidste måneds værdi. Gem ændringerne i aendring. Første plads skal være NA, da der ikke findes en foregående måned.','aendring <- rep(NA_real_, length(indeks))\nfor (i in 2:length(indeks)) {\n  aendring[i] <- indeks[i] - indeks[i - 1]\n}',{source:'consumer',setup:'indeks <- c(15.5, 11.8, 10.4, 11.1, 11.7, 9.3, 8.6, 10.4, 9.3, 9.3, 10.7, 7.4)',level:4,hint:'Lav først en vektor af samme længde med NA. Start løkken ved position 2, så hver måned kan sammenlignes med position i - 1.',check:loopCheck('aendring',[{setup:'indeks <- c(15.5, 11.8, 10.4, 11.1, 11.7, 9.3, 8.6, 10.4, 9.3, 9.3, 10.7, 7.4)',reference:'aendring <- rep(NA_real_, length(indeks)); for (i in 2:length(indeks)) aendring[i] <- indeks[i] - indeks[i - 1]'},{setup:'indeks <- c(-2, 0, 3.5, 1, 4)',reference:'aendring <- rep(NA_real_, length(indeks)); for (i in 2:length(indeks)) aendring[i] <- indeks[i] - indeks[i - 1]'}])});
add('u-loop-sim','functions','Tæl udfald i flere simuleringer','Vektoren kast indeholder terningekast, og forsog angiver hvilket forsøg hvert kast hører til. Brug en for-løkke til at tælle seksere i hvert forsøg. Gem de navngivne tællinger i antal_seks; navnene skal være forsøgsnumrene.','forsogsnumre <- unique(forsog)\nantal_seks <- rep(0L, length(forsogsnumre))\nnames(antal_seks) <- forsogsnumre\nfor (i in seq_along(forsogsnumre)) {\n  antal_seks[i] <- sum(kast[forsog == forsogsnumre[i]] == 6)\n}',{source:'dice',setup:'kast <- c(1, 6, 3, 6, 2, 4, 6, 5, 1, 2, 6, 6)\nforsog <- rep(1:3, each = 4)',level:4,hint:'Find først forsøgsnumrene. Gennemløb dem én ad gangen, vælg kast fra det aktuelle forsøg, og tæl hvor mange der er 6.',check:loopCheck('antal_seks',[{setup:'kast <- c(1, 6, 3, 6, 2, 4, 6, 5, 1, 2, 6, 6); forsog <- rep(1:3, each = 4)',reference:'forsogsnumre <- unique(forsog); antal_seks <- rep(0L, length(forsogsnumre)); names(antal_seks) <- forsogsnumre; for (i in seq_along(forsogsnumre)) antal_seks[i] <- sum(kast[forsog == forsogsnumre[i]] == 6)'},{setup:'kast <- c(6, 2, 6, 1, 3, 4, 6, 6, 5, 5); forsog <- c(1, 1, 2, 2, 2, 3, 3, 3, 4, 4)',reference:'forsogsnumre <- unique(forsog); antal_seks <- rep(0L, length(forsogsnumre)); names(antal_seks) <- forsogsnumre; for (i in seq_along(forsogsnumre)) antal_seks[i] <- sum(kast[forsog == forsogsnumre[i]] == 6)'}])});
add('u-loop-flights','functions','Sammenfat flyspor','Dataframen spor indeholder flere flyvninger med højdemålinger i tidsrækkefølge. Brug en for-løkke til at beregne hver flyvnings samlede stigning: læg kun positive højdeforskelle mellem målinger sammen. Gem resultatet i en navngiven vektor stigning med ét tal pr. fly.','fly <- unique(spor$fly)\nstigning <- rep(0, length(fly))\nnames(stigning) <- fly\nfor (i in seq_along(fly)) {\n  hoejde <- spor$hoejde[spor$fly == fly[i]]\n  forskel <- diff(hoejde)\n  stigning[i] <- sum(forskel[forskel > 0])\n}',{source:'flight',setup:'spor <- data.frame(fly = c("SAS1", "SAS1", "SAS1", "DLH2", "DLH2", "DLH2"), tid = c(1, 2, 3, 1, 2, 3), hoejde = c(0, 1000, 600, 0, 500, 1200))',level:4,hint:'Gennemløb de unikke fly-id’er. For hvert id skal du hente dets højder i rækkefølge, finde forskellene mellem nabomålinger og kun summere de positive.',check:loopCheck('stigning',[{setup:'spor <- data.frame(fly = c("SAS1", "SAS1", "SAS1", "DLH2", "DLH2", "DLH2"), tid = c(1, 2, 3, 1, 2, 3), hoejde = c(0, 1000, 600, 0, 500, 1200))',reference:'fly <- unique(spor$fly); stigning <- rep(0, length(fly)); names(stigning) <- fly; for (i in seq_along(fly)) { hoejde <- spor$hoejde[spor$fly == fly[i]]; forskel <- diff(hoejde); stigning[i] <- sum(forskel[forskel > 0]) }'},{setup:'spor <- data.frame(fly = c("A", "A", "A", "B", "B", "C", "C"), tid = c(1, 2, 3, 1, 2, 1, 2), hoejde = c(0, 500, 900, 0, 1000, 0, 350))',reference:'fly <- unique(spor$fly); stigning <- rep(0, length(fly)); names(stigning) <- fly; for (i in seq_along(fly)) { hoejde <- spor$hoejde[spor$fly == fly[i]]; forskel <- diff(hoejde); stigning[i] <- sum(forskel[forskel > 0]) }'}])});
add('u-vector','functions','Tænk i hele vektorer','Beregn gennemsnittet af vektoren priser. Træk dette gennemsnit fra hver pris. Returnér alle forskellene som en vektor i samme rækkefølge som priser.','priser - mean(priser)',{source:'loops',setup:'priser <- c(120, 250, 80, 190)',hint:'Én beregning kan udføres på alle værdier samtidig.'});
add('u-ifelse','functions','Kategorisér alder','Lav én tekstværdi for hver værdi i vektoren alder: "voksen", hvis alderen er 18 eller derover, og "barn", hvis den er under 18. Returnér tekstværdierne i samme rækkefølge som alder.','ifelse(alder >= 18, "voksen", "barn")',{source:'list',setup:'alder <- c(12, 18, 17, 45, 21)',level:2,hint:'ifelse(betingelse, hvis_sand, hvis_falsk) arbejder på en vektor.'});
add('u-apply','functions','Gennemsnit af hver liste','Beregn ét gennemsnit for hver del af listen loeb: ét for DHL og ét for park. Returnér de to tal som en vektor med navnene DHL og park, ikke som en liste.','sapply(loeb, mean)',{source:'list',setup:'loeb <- list(DHL = c(18, 20, 22), park = c(12, 16, 20))',level:2,hint:'sapply() anvender en funktion på hvert element og forsøger at forenkle resultatet.'});
add('s-mean','stats','Gennemsnitlig brændstoføkonomi','Returnér gennemsnittet af mpg.','mean(biler$mpg)',{setup:car,hint:'Brug mean() på den relevante kolonne.'});
add('s-na','stats','Gennemsnit med huller','Returnér gennemsnittet af x, uden at manglende værdier påvirker resultatet.','mean(x, na.rm = TRUE)',{setup:'x <- c(7, 4, NA, 10, 12)',source:'clean',hint:'Argumentet na.rm = TRUE fjerner NA fra beregningen.'});
add('s-count','stats','Hvor mange værdier mangler?','Returnér antallet af NA i x.','sum(is.na(x))',{setup:'x <- c(7, NA, 4, NA, 10)',source:'clean',hint:'TRUE tæller som 1, når du summerer en logisk vektor.'});
add('s-clean','stats','Rens bilernes data','Returnér kun de rækker, hvor mpg ikke mangler.','biler[!is.na(biler$mpg), ]',{setup:'biler <- data.frame(mpg = c(20, NA, 25, 18, NA), pris = c(80, 90, 120, 70, 95))',source:'clean',level:2,hint:'!is.na(...) er TRUE for kendte værdier.'});
add('s-sd','stats','Mål spredningen','Returnér stikprøvens standardafvigelse for priser.','sd(priser)',{setup:'priser <- c(120, 250, 80, 190)',source:'loops',hint:'sd() bruger n − 1 i nævneren for variansen.'});
add('s-group','stats','Sammenlign cylindergrupper','Returnér et data frame med gennemsnitlig mpg for hver cyl-gruppe. Brug aggregate().','aggregate(mpg ~ cyl, data = biler, FUN = mean)',{setup:car,level:2,hint:'aggregate(værdi ~ gruppe, data = datasæt, FUN = mean).'});
add('s-table','stats','Tæl biler i hver gruppe','Tæl, hvor mange biler der har hver værdi i kolonnen cyl. Returnér en frekvenstabel med table(), så antallet af biler med 4, 6 og 8 cylindre fremgår.','table(biler$cyl)',{setup:car,hint:'table() tæller forekomsterne af hver værdi.'});
add('s-na-debug','stats','Ret fejlen: sammenligning med NA','Ret koden, så kun de kendte værdier returneres.','x[!is.na(x)]',{setup:'x <- c(3, NA, 7, 9)',source:'clean',kind:'debug',starter:'x[x != NA]',hint:'NA er ukendt. Brug is.na() til at teste for manglende værdier.'});
add('m-dice','simulation','Kast en terning 100 gange','Opret en vektor med navnet kast med 100 tilfældige terningekast. Hvert kast skal være et helt tal fra 1 til 6, og alle seks tal skal være lige sandsynlige. Brug sample(), og tillad at samme tal trækkes flere gange.','kast <- sample(1:6, 100, replace = TRUE)',{source:'dice',level:2,hint:'Med replace = TRUE kan samme side trækkes flere gange.',check:'is.numeric(kast) && length(kast) == 100 && all(kast %in% 1:6) && any(all.names(.user_expr) == "sample")'});
add('m-prob','simulation','Andelen af seksere','Beregn, hvor stor en andel af værdierne i vektoren kast der er 6. Brug formlen: andel = antal seksere / antal kast. Returnér ét tal mellem 0 og 1, ikke en procent.','mean(kast == 6)',{source:'dice',setup:'kast <- c(1, 6, 3, 6, 2, 4, 6, 5, 1, 2)',hint:'Gennemsnittet af en logisk vektor er andelen af TRUE.'});
add('m-replicate','simulation','Gentag en simulation','Opret en vektor med navnet summer. Simulér to seks-sidede terningekast, læg de to kast sammen, og gentag hele forsøget 200 gange med replicate(). Vektoren skal indeholde 200 summer. Samme terningetal må trækkes flere gange.','summer <- replicate(200, sum(sample(1:6, 2, replace = TRUE)))',{source:'dice',level:3,hint:'replicate(antal, udtryk) gentager en beregning.',check:'is.numeric(summer) && length(summer) == 200 && all(summer >= 2 & summer <= 12 & summer == floor(summer)) && all(c("replicate", "sample") %in% all.names(.user_expr))'});
add('m-seed','simulation','Hvorfor sætte et seed?','Hvad er formålet med set.seed(42) før sample()?','Gøre tilfældige resultater reproducerbare',{source:'dice',kind:'choice',options:['Sikre præcis lige mange af hver værdi','Gøre tilfældige resultater reproducerbare','Sortere resultaterne','Fjerne tilfældigheden fra modellen'],answer:1,hint:'Det styrer starttilstanden for tilfældighedsgeneratoren.'});
add('m-quarter','simulation','Fra måneder til kvartaler','Vektoren maaned indeholder månedsnumrene 1 til 12. Returnér kvartalsnummeret for hver måned: januar–marts er 1, april–juni er 2, juli–september er 3 og oktober–december er 4. Bevar månedernes rækkefølge.','ceiling(maaned / 3)',{source:'macro',setup:'maaned <- 1:12',level:2,hint:'Divider måneden med 3, og rund op med ceiling().'});
add('m-growth','simulation','Årlig vækst','Beregn væksten i procent fra foer til nu for hvert par af værdier. Brug formlen: vækst i procent = (nu / foer - 1) * 100. Returnér én vækstrate pr. par i samme rækkefølge som vektorerne.','(nu / foer - 1) * 100',{source:'macro',setup:'foer <- c(100, 200, 80)\nnu <- c(105, 190, 88)',level:2,hint:'Procentvis vækst er (ny / gammel − 1) × 100.'});
add('m-lm','simulation','Din første regressionsmodel','Opret en lineær regressionsmodel med navnet model ud fra datasættet biler. Modellen skal forklare mpg ud fra wt: mpg er y (det, der forklares), og wt er x (den forklarende variabel). Brug lm().','model <- lm(mpg ~ wt, data = biler)',{setup:car,source:'model',level:3,hint:'lm(y ~ x, data = ...) tilpasser en lineær model.',check:'inherits(model, "lm") && isTRUE(all.equal(coef(model), coef(lm(mpg ~ wt, data=mtcars))))'});
add('m-r2','simulation','Forklaringsgrad','Hent R², også kaldet forklaringsgraden, fra den allerede oprettede model. Returnér selve tallet mellem 0 og 1, ikke en procent eller hele modeloversigten.','summary(model)$r.squared',{setup:'model <- lm(mpg ~ wt, data = mtcars)',source:'model',level:3,hint:'summary(model) indeholder r.squared.'});
add('m-merge','simulation','Saml data på kvartal','Saml datasættene forbrug og tillid ved at matche værdierne i deres kolonne kvartal. Returnér ét datasæt med kolonnerne kvartal, forbrug og tillid. Medtag kun kvartaler, der findes i begge datasæt.','merge(forbrug, tillid, by = "kvartal")',{source:'macro',level:3,setup:'forbrug <- data.frame(kvartal = c("2024K1", "2024K2", "2024K3"), forbrug = c(100, 104, 106))\ntillid <- data.frame(kvartal = c("2024K1", "2024K2"), tillid = c(-5, -2))',hint:'Brug merge(forbrug, tillid, by = "kvartal"). by angiver den kolonne, som rækkerne skal matches på. Som standard beholdes kun kvartaler, der findes i begge datasæt.'});

addExamSheetExercises(add);
