add("extra-vectors-1", "vectors", "Målinger i en vektor", "Saml målingerne 12, 15 og 11 i en numerisk vektor.", "c(12, 15, 11)", {"setup":"","hint":"Brug c() til at samle værdier.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-2", "vectors", "Hvert fjerde tal", "Returnér 6 tal. Start ved 3, og læg 4 til hver gang.", "seq(from=3, by=4, length.out=6)", {"setup":"","hint":"Brug by og length.out i seq().","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-3", "vectors", "Gentag en kode", "Returnér koden DK tre gange i en tekstvektor.", "rep('DK', 3)", {"setup":"","hint":"rep() kan gentage tekst.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-4", "vectors", "Gentag et mønster", "Gentag hele mønstret A, B tre gange.", "rep(c('A','B'), times=3)", {"setup":"","hint":"Brug times til at gentage hele vektoren.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-5", "vectors", "Første og sidste måling", "Returnér første og sidste værdi fra x, i den rækkefølge.", "x[c(1, length(x))]", {"setup":"x <- c(16, 8, 23, 10, 4)","hint":"length(x) giver den sidste position.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-6", "vectors", "Behold tre positioner", "Returnér værdierne på plads 2, 4 og 5 fra x.", "x[c(2, 4, 5)]", {"setup":"x <- c(14, 22, 9, 18, 30, 1)","hint":"Saml positionerne i en vektor.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-7", "vectors", "Spring anden plads over", "Returnér x uden værdien på plads 2. Behold rækkefølgen.", "x[-2]", {"setup":"x <- c(4, 9, 9, 2)","hint":"Et negativt indeks udelader en position.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-8", "vectors", "Vend en vektor", "Returnér x i omvendt rækkefølge.", "rev(x)", {"setup":"x <- c(5, 3, 11, 7)","hint":"rev() vender rækkefølgen.","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-9", "vectors", "Teksttal til tal", "Lav tekstværdierne i x om til en numerisk vektor.", "as.numeric(x)", {"setup":"x <- c('12', '4.5', '0')","hint":"Brug as.numeric().","check":null,"source":"intro","level":1,"extra":true});
add("extra-vectors-10", "vectors", "Find datatypen", "Returnér datatypen for x som tekst med typeof().", "typeof(x)", {"setup":"x <- c(TRUE, FALSE, TRUE)","hint":"typeof(x) returnerer typen som tekst.","check":null,"source":"intro","level":1,"extra":true});
