add("extra-simulation-10", "simulation", "Forudsig salg i uge 6", "Tilpas lm(salg ~ uge, data = salgstal), og brug predict() til at forudsige salget i uge 6. Returnér ét tal.", "unname(predict(lm(salg ~ uge,data=salgstal),newdata=data.frame(uge=6)))", {"setup":"salgstal <- data.frame(uge=1:5,salg=c(10,13,15,19,20))","hint":"Gem modellen i en variabel, så du kan bruge den i næste trin.","check":null,"source":"model","level":2,"extra":true});
