add("extra-for-loops-1", "for-loops", "Gentag en hilsen", "Brug en for-løkke. Skriv 'Hej' én gang pr. plads i resultat. Returnér resultat.", "resultat <- character(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- 'Hej'\n}\nresultat", {"setup":"tal <- c(-5, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(-5, 0, 4, -2)","reference":"resultat <- rep('Hej',length(tal))"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- rep('Hej',length(tal))"}])});
add("extra-for-loops-2", "for-loops", "Gem tallene i samme rækkefølge", "Brug en for-løkke. Kopiér hvert tal fra tal til resultat. Returnér resultat.", "resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- tal[i]\n}\nresultat", {"setup":"tal <- c(-4, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(-4, 0, 4, -2)","reference":"resultat <- tal"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- tal"}])});
add("extra-for-loops-3", "for-loops", "Læg 3 til hvert tal", "Brug en for-løkke. Gem hvert tal plus 3 på den tilsvarende plads i resultat. Returnér resultat.", "resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- tal[i] + 3\n}\nresultat", {"setup":"tal <- c(-3, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(-3, 0, 4, -2)","reference":"resultat <- tal+3"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- tal+3"}])});
add("extra-for-loops-4", "for-loops", "Gang med positionen", "Brug en for-løkke. Gang hvert tal med dets position, og gem værdien i resultat. Returnér resultat.", "resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- tal[i] * i\n}\nresultat", {"setup":"tal <- c(-2, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(-2, 0, 4, -2)","reference":"resultat <- tal*seq_along(tal)"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- tal*seq_along(tal)"}])});
add("extra-for-loops-5", "for-loops", "Saml kvadraterne", "Brug en for-løkke. Gem kvadratet af hvert tal i resultat. Returnér resultat.", "resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- tal[i]^2\n}\nresultat", {"setup":"tal <- c(-1, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(-1, 0, 4, -2)","reference":"resultat <- tal^2"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- tal^2"}])});
add("extra-for-loops-6", "for-loops", "Vend rækkefølgen med en løkke", "Brug en for-løkke. Gem tallene fra tal i omvendt rækkefølge i resultat. Returnér resultat.", "resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- tal[length(tal) - i + 1]\n}\nresultat", {"setup":"tal <- c(0, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(0, 0, 4, -2)","reference":"resultat <- rev(tal)"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- rev(tal)"}])});
add("extra-for-loops-7", "for-loops", "Tæl negative tal", "Brug en for-løkke. Start resultat på 0 og tæl de værdier, der er mindre end 0. Returnér resultat.", "resultat <- 0\nfor (i in seq_along(tal)) {\n  if (tal[i] < 0) resultat <- resultat + 1\n}\nresultat", {"setup":"tal <- c(1, 0, 4, -2)","hint":"Start tælleren eller summen før løkken, og opdatér den i if-blokken.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(1, 0, 4, -2)","reference":"resultat <- sum(tal<0)"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- sum(tal<0)"}])});
add("extra-for-loops-8", "for-loops", "Tæl nuller", "Brug en for-løkke. Start resultat på 0 og tæl værdier, der er lig med 0. Returnér resultat.", "resultat <- 0\nfor (i in seq_along(tal)) {\n  if (tal[i] == 0) resultat <- resultat + 1\n}\nresultat", {"setup":"tal <- c(2, 0, 4, -2)","hint":"Start tælleren eller summen før løkken, og opdatér den i if-blokken.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(2, 0, 4, -2)","reference":"resultat <- sum(tal==0)"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- sum(tal==0)"}])});
add("extra-for-loops-9", "for-loops", "Summér kun positive tal", "Brug en for-løkke. Start resultat på 0 og læg kun værdier over 0 til summen. Returnér resultat.", "resultat <- 0\nfor (i in seq_along(tal)) {\n  if (tal[i] > 0) resultat <- resultat + tal[i]\n}\nresultat", {"setup":"tal <- c(3, 0, 4, -2)","hint":"Start tælleren eller summen før løkken, og opdatér den i if-blokken.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(3, 0, 4, -2)","reference":"resultat <- sum(tal[tal>0])"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- sum(tal[tal>0])"}])});
add("extra-for-loops-10", "for-loops", "Markér positive tal", "Brug en for-løkke. Gem TRUE for positive tal og FALSE for resten på den tilsvarende plads i resultat. Returnér resultat.", "resultat <- logical(length(tal))\nfor (i in seq_along(tal)) {\n  resultat[i] <- tal[i] > 0\n}\nresultat", {"setup":"tal <- c(4, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":1,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(4, 0, 4, -2)","reference":"resultat <- tal>0"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- tal>0"}])});
add("extra-for-loops-11", "for-loops", "Erstat negative værdier", "Brug en for-løkke. Gem hvert tal i resultat, men erstat negative værdier med 0. Returnér resultat.", "resultat <- numeric(length(tal))\nfor (i in seq_along(tal)) {\n  if (tal[i] < 0) {\n    resultat[i] <- 0\n  } else {\n    resultat[i] <- tal[i]\n  }\n}\nresultat", {"setup":"tal <- c(5, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":2,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(5, 0, 4, -2)","reference":"resultat <- pmax(tal,0)"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- pmax(tal,0)"}])});
add("extra-for-loops-12", "for-loops", "Gem løbende summer", "Brug en for-løkke. Gem den løbende sum i resultat. Første plads er første tal. Hver næste plads er summen til og med den plads. Returnér resultat.", "resultat <- numeric(length(tal))\nsum_indtil_nu <- 0\nfor (i in seq_along(tal)) {\n  sum_indtil_nu <- sum_indtil_nu + tal[i]\n  resultat[i] <- sum_indtil_nu\n}\nresultat", {"setup":"tal <- c(6, 0, 4, -2)","hint":"Brug seq_along(tal) og gem resultatet på plads i.","source":"loops","level":2,"extra":true, "check":loopCheck('resultat', [{"setup":"tal <- c(6, 0, 4, -2)","reference":"resultat <- cumsum(tal)"},{"setup":"tal <- c(3, -4, 0, 0, 8, 1)","reference":"resultat <- cumsum(tal)"}])});

